  8→// kiroFileModificationTools lists tool names that create or modify files.
  9→var kiroFileModificationTools = []string{"fs_write", "fs_edit"}
 10→
 11→// parseTranscript unmarshals raw JSON into a kiroTranscript, supporting both
 12→// Kiro CLI format (paired user+assistant entries) and Kiro IDE format
 13→// (sequential {role, content} messages). IDE format is converted to CLI format
 14→// so all downstream extraction functions work unchanged.
 15→//
 16→// Returns an empty transcript (not an error) for empty or "{}" input,
 17→// matching the placeholder transcript created in IDE mode.
 18→func parseTranscript(data []byte) (*kiroTranscript, error) {
 19→	if len(data) == 0 {
 20→		return &kiroTranscript{}, nil
 21→	}
 22→
 23→	// Detect format by checking which structure produces meaningful data.
 24→	// Both formats have a "history" array, but CLI format has "user"/"assistant"
 25→	// subfields while IDE format has "message" with "role"/"content".
 26→	// Since json.Unmarshal silently ignores unknown fields, we try both and
 27→	// check which one has non-empty content.
 28→
 29→	// Try CLI format first (has "conversation_id" and paired user+assistant entries).
 30→	var t kiroTranscript
 31→	if err := json.Unmarshal(data, &t); err != nil {
 32→		return nil, fmt.Errorf("failed to parse kiro transcript: %w", err)
 33→	}
 34→	if isCLITranscript(&t) {
 35→		return &t, nil
 36→	}
 37→
 38→	// Try IDE format (sequential {role, content} messages).
 39→	converted := tryParseIDETranscript(data)
 40→	if converted != nil {
 41→		return converted, nil
 42→	}
 43→
 44→	return &t, nil
 45→}
 46→
 47→// isCLITranscript checks whether a parsed kiroTranscript contains actual CLI-format
 48→// data (with populated user/assistant fields) rather than zero-valued entries
 49→// from unmarshalling a different format.
 50→func isCLITranscript(t *kiroTranscript) bool {
 51→	if len(t.History) == 0 {
 52→		return false
 53→	}
 54→	// CLI format entries have user content; IDE format entries would have empty
 55→	// user/assistant fields when unmarshalled into kiroHistoryEntry.
 56→	return len(t.History[0].User.Content) > 0 || len(t.History[0].Assistant) > 0
 57→}
 58→
 59→// tryParseIDETranscript attempts to parse data as a Kiro IDE transcript.
 60→// Returns the converted transcript if successful, or nil if the data doesn't
 61→// contain IDE-format history entries.
 62→func tryParseIDETranscript(data []byte) *kiroTranscript {
 63→	var ide kiroIDETranscript
 64→	if err := json.Unmarshal(data, &ide); err != nil {
 65→		return nil
 66→	}
 67→	if len(ide.History) == 0 {
 68→		return nil
 69→	}
 70→	// Verify it's actually IDE format by checking the first entry has a role.
 71→	if ide.History[0].Message.Role == "" {
 72→		return nil
 73→	}
 74→	return convertIDETranscript(&ide)
 75→}
 76→
 77→// convertIDETranscript converts IDE sequential messages into paired
 78→// kiroHistoryEntry entries so downstream extraction functions work unchanged.
 79→// It pairs consecutive user+assistant messages; unpaired messages at the end
 80→// are included with empty counterparts.
 81→func convertIDETranscript(ide *kiroIDETranscript) *kiroTranscript {
 82→	t := &kiroTranscript{}
 83→
 84→	var pendingUser *kiroIDEHistoryEntry
 85→	for i := range ide.History {
 86→		entry := &ide.History[i]
 87→		role := entry.Message.Role
 88→
 89→		switch role {
 90→		case "user":
 91→			// If we already have a pending user, flush it without an assistant.
 92→			if pendingUser != nil {
 93→				t.History = append(t.History, ideEntryToPaired(pendingUser, nil))
 94→			}
 95→			pendingUser = entry
 96→		case "assistant":
 97→			t.History = append(t.History, ideEntryToPaired(pendingUser, entry))
 98→			pendingUser = nil
 99→		}
100→	}
101→
102→	// Flush any trailing user message without an assistant response.
103→	if pendingUser != nil {
104→		t.History = append(t.History, ideEntryToPaired(pendingUser, nil))
105→	}
106→
107→	return t
108→}
109→
110→// ideEntryToPaired converts an IDE user+assistant message pair into a
111→// kiroHistoryEntry. Either user or assistant may be nil.
112→func ideEntryToPaired(user, assistant *kiroIDEHistoryEntry) kiroHistoryEntry {
113→	entry := kiroHistoryEntry{}
114→
115→	if user != nil {
116→		// Convert IDE user content to CLI format.
117→		// IDE: [{"type":"text","text":"..."}] → CLI: {"Prompt":{"prompt":"..."}}
118→		prompt := extractIDEUserText(user.Message.Content)
119→		if prompt != "" {
120→			content, marshalErr := json.Marshal(kiroPromptContent{
121→				Prompt: struct {
122→					Prompt string `json:"prompt"`
123→				}{Prompt: prompt},
124→			})
125→			if marshalErr == nil {
126→				entry.User.Content = content
127→			}
128→		} else {
129→			entry.User.Content = user.Message.Content
130→		}
131→	}
132→
133→	if assistant != nil {
134→		// Convert IDE assistant content to CLI format.
135→		// IDE: "text string" → CLI: {"Response":{"message_id":"","content":"..."}}
136→		text := extractIDEAssistantText(assistant.Message.Content)
137→		if text != "" {
138→			content, marshalErr := json.Marshal(kiroResponseContent{
139→				Response: kiroResponsePayload{Content: text},
140→			})
141→			if marshalErr == nil {
142→				entry.Assistant = content
143→			}
144→		} else {
145→			entry.Assistant = assistant.Message.Content
146→		}
147→	}
148→
149→	return entry
150→}
151→
152→// extractIDEUserText extracts the text from an IDE user message's content.
153→// Handles both array format [{"type":"text","text":"..."}] and plain string.
154→func extractIDEUserText(content json.RawMessage) string {
155→	if len(content) == 0 {
156→		return ""
157→	}
158→
159→	// Try array of content blocks.
160→	var blocks []kiroIDEContentBlock
161→	if err := json.Unmarshal(content, &blocks); err == nil && len(blocks) > 0 {
162→		for _, b := range blocks {
163→			if b.Type == "text" && b.Text != "" {
164→				return b.Text
165→			}
166→		}
167→		return ""
168→	}
169→
170→	// Try plain string.
171→	var s string
172→	if err := json.Unmarshal(content, &s); err == nil {
173→		return s
174→	}
175→
176→	return ""
177→}
178→
179→// extractIDEAssistantText extracts the text from an IDE assistant message's content.
180→// Handles both plain string and array format.
181→func extractIDEAssistantText(content json.RawMessage) string {
182→	if len(content) == 0 {
183→		return ""
184→	}
185→
186→	// Try plain string (most common for assistant).
187→	var s string
188→	if err := json.Unmarshal(content, &s); err == nil {
189→		return s
190→	}
191→
192→	// Try array of content blocks.
193→	var blocks []kiroIDEContentBlock
194→	if err := json.Unmarshal(content, &blocks); err == nil && len(blocks) > 0 {
195→		for _, b := range blocks {
196→			if b.Type == "text" && b.Text != "" {
197→				return b.Text
198→			}
199→		}
200→	}
201→
202→	return ""
203→}
204→
205→// extractUserPrompt tries to extract a prompt string from a user message's
206→// raw content. Returns "" if the content is a ToolUseResults variant or
207→// cannot be parsed.
208→func extractUserPrompt(content json.RawMessage) string {
209→	if len(content) == 0 {
210→		return ""
211→	}
212→
213→	var pc kiroPromptContent
214→	if err := json.Unmarshal(content, &pc); err == nil && pc.Prompt.Prompt != "" {
215→		return pc.Prompt.Prompt
216→	}
217→	return ""
218→}
219→
220→// extractModifiedFilesFromHistory returns deduplicated file paths modified by
221→// tool calls across the given history entries.
222→func extractModifiedFilesFromHistory(entries []kiroHistoryEntry) []string {
223→	seen := make(map[string]bool)
224→	var files []string
225→
226→	for i := range entries {
227→		for _, path := range extractFilesFromAssistant(entries[i].Assistant) {
228→			if path != "" && !seen[path] {
229→				seen[path] = true
230→				files = append(files, path)
231→			}
232→		}
233→	}
234→	return files
235→}
236→
237→// extractFilesFromAssistant extracts file paths from an assistant message's
238→// raw JSON. Returns nil if the message is not a ToolUse variant.
239→func extractFilesFromAssistant(raw json.RawMessage) []string {
240→	if len(raw) == 0 {
241→		return nil
242→	}
243→
244→	var tc kiroToolUseContent
245→	if err := json.Unmarshal(raw, &tc); err != nil || len(tc.ToolUse.ToolUses) == 0 {
246→		return nil
247→	}
248→
249→	var paths []string
250→	for _, call := range tc.ToolUse.ToolUses {
251→		if !isFileModificationTool(call.Name) {
252→			continue
253→		}
254→		if p := extractFilePath(call.Args); p != "" {
255→			paths = append(paths, p)
256→		}
257→	}
258→	return paths
259→}
260→
261→// isFileModificationTool reports whether the tool name is a file-modifying tool.
262→func isFileModificationTool(name string) bool {
263→	for _, t := range kiroFileModificationTools {
264→		if name == t {
265→			return true
266→		}
267→	}
268→	return false
269→}
270→
271→// extractFilePath extracts a file path from tool call args JSON.
272→// Checks "path", "file_path", and "filename" keys in order.
273→func extractFilePath(args json.RawMessage) string {
274→	if len(args) == 0 {
275→		return ""
276→	}
277→
278→	var m map[string]json.RawMessage
279→	if err := json.Unmarshal(args, &m); err != nil {
280→		return ""
281→	}
282→
283→	for _, key := range []string{"path", "file_path", "filename"} {
284→		raw, ok := m[key]
285→		if !ok {
286→			continue
287→		}
288→		var s string
289→		if err := json.Unmarshal(raw, &s); err == nil && s != "" {
290→			return s
291→		}
292→	}
293→	return ""
294→}
295→
296→// extractLastAssistantResponse walks the history backward and returns the
297→// content of the last Response-type assistant message.
298→func extractLastAssistantResponse(entries []kiroHistoryEntry) string {
299→	for i := len(entries) - 1; i >= 0; i-- {
300→		if len(entries[i].Assistant) == 0 {
301→			continue
302→		}
303→		var rc kiroResponseContent
304→		if err := json.Unmarshal(entries[i].Assistant, &rc); err == nil && rc.Response.Content != "" {
305→			return rc.Response.Content
306→		}
307→	}
308→	return ""
309→}
